<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>硬币投掷：恰好 k 次正面的概率</title>
<style>
  :root{--bg:#0f1720;--fg:#e8eef5;--accent:#4fc3f7;--muted:#8aa0b4;--panel:#18232e;
        --bar:#3a5570;--target:#ffb74d;--sim:#66bb6a;--peak:#8e9bff;}
  *{box-sizing:border-box;}
  body{margin:0;background:var(--bg);color:var(--fg);font-family:system-ui,-apple-system,"Segoe UI",sans-serif;padding:16px;}
  h1{font-size:1.15rem;margin:0 0 4px;}
  .sub{color:var(--muted);font-size:.85rem;margin-bottom:14px;line-height:1.5;}
  .wrap{display:grid;grid-template-columns:1fr 320px;gap:16px;align-items:start;}
  @media(max-width:840px){.wrap{grid-template-columns:1fr;}}
  .card{background:var(--panel);border:1px solid #263646;border-radius:10px;padding:10px;}
  canvas{width:100%;height:auto;display:block;border-radius:6px;background:#0b131b;}
  .panel{background:var(--panel);border:1px solid #263646;border-radius:10px;padding:14px;}
  .ctrl{margin-bottom:14px;}
  .ctrl:last-of-type{margin-bottom:0;}
  label{display:flex;justify-content:space-between;align-items:baseline;font-size:.9rem;margin-bottom:6px;}
  .val{color:var(--accent);font-variant-numeric:tabular-nums;font-weight:600;}
  input[type=range]{width:100%;accent-color:var(--accent);}
  .readout{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:14px;}
  .mini{background:#0b131b;border:1px solid #223141;border-radius:8px;padding:8px 10px;}
  .mini .k{font-size:.72rem;color:var(--muted);}
  .mini .v{font-size:.92rem;color:var(--accent);font-variant-numeric:tabular-nums;font-weight:600;}
  .mini.wide{grid-column:1 / -1;}
  .assume{font-size:.75rem;color:var(--muted);line-height:1.6;margin-top:12px;border-top:1px dashed #2c3d4e;padding-top:9px;}
  .assume b{color:#c7d6e4;}
  .btns{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:12px;}
  button{background:#22364a;color:var(--fg);border:1px solid #33506b;border-radius:8px;padding:8px;font-size:.8rem;cursor:pointer;font-family:inherit;}
  button:hover{background:#2c4863;}
  .hint{font-size:.75rem;color:var(--muted);margin-top:8px;line-height:1.5;}
  .legend{display:flex;flex-wrap:wrap;gap:10px;font-size:.75rem;color:var(--muted);margin-top:8px;}
  .legend i{display:inline-block;width:10px;height:10px;border-radius:2px;margin-right:4px;vertical-align:middle;}
